  <a class="skip-link" href="#quiz">Skip to main content</a>
  <main class="page" id="main">
    <div class="shell">
      <header class="hero">
        <h1>Computer Languages Quiz</h1>
        <p>Select every answer that applies for each question. Some questions may have more than one correct choice.</p>
      </header>

      <form id="quiz" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="q1-help">
            <legend>1. Which of these are programming languages?</legend>
            <p class="help-text" id="q1-help">Pick every option that is used to write software.</p>
            <div class="choices">
              <label class="choice">
                <input type="checkbox" name="q1" value="python" />
                <span>
                  <strong>Python</strong>
                  <small>A general-purpose programming language.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q1" value="html" />
                <span>
                  <strong>HTML</strong>
                  <small>A markup language for structuring web content.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q1" value="javascript" />
                <span>
                  <strong>JavaScript</strong>
                  <small>A scripting language for web interactivity.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q1" value="css" />
                <span>
                  <strong>CSS</strong>
                  <small>A style sheet language for presentation.</small>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages are commonly used for web development?</legend>
            <div class="choices">
              <label class="choice">
                <input type="checkbox" name="q2" value="javascript" />
                <span>
                  <strong>JavaScript</strong>
                  <small>Runs in browsers and on servers.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q2" value="rust" />
                <span>
                  <strong>Rust</strong>
                  <small>Often used for systems and web backends.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q2" value="html" />
                <span>
                  <strong>HTML</strong>
                  <small>Defines the structure of web pages.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q2" value="css" />
                <span>
                  <strong>CSS</strong>
                  <small>Controls layout and styling for the web.</small>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which of these are compiled languages?</legend>
            <div class="choices">
              <label class="choice">
                <input type="checkbox" name="q3" value="go" />
                <span>
                  <strong>Go</strong>
                  <small>Compiled to native machine code.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q3" value="python" />
                <span>
                  <strong>Python</strong>
                  <small>Typically interpreted at runtime.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q3" value="csharp" />
                <span>
                  <strong>C#</strong>
                  <small>Compiled to intermediate language.</small>
                </span>
              </label>
              <label class="choice">
                <input type="checkbox" name="q3" value="sql" />
                <span>
                  <strong>SQL</strong>
                  <small>A language for working with databases.</small>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
        </div>
        <div class="result" id="result" aria-live="polite"></div>
      </form>
    </div>
  </main>

  <script>
    const answers = {
      q1: new Set(["python", "javascript"]),
      q2: new Set(["javascript", "html", "css"]),
      q3: new Set(["go", "csharp"])
    };

    const labels = {
      python: "Python",
      html: "HTML",
      javascript: "JavaScript",
      css: "CSS",
      rust: "Rust",
      go: "Go",
      csharp: "C#",
      sql: "SQL"
    };

    const form = document.getElementById("quiz");
    const result = document.getElementById("result");

    function getSelectedValues(name) {
      return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const score = Object.keys(answers).reduce((total, key) => {
        const selected = getSelectedValues(key);
        const correct = answers[key];
        const exactMatch =
          selected.length === correct.size &&
          selected.every((value) => correct.has(value));

        return total + (exactMatch ? 1 : 0);
      }, 0);

      const summary = Object.entries(answers).map(([key, correct]) => {
        const selected = getSelectedValues(key).map((value) => labels[value]);
        return `Question ${key.slice(1)}: ${selected.length ? selected.join(", ") : "no answers selected"}`;
      }).join(" | ");

      result.textContent = `You answered ${score} of 3 questions exactly right. ${summary}`;
    });
  </script>
